from fastapi import FastAPI, Request, Response, Form, Depends, Cookie
from fastapi.responses import HTMLResponse, RedirectResponse
from pydantic import BaseModel
import hashlib
import hmac
import time
import os
import httpx

app = FastAPI()

# In-memory user store for demo
users_db = {
    "admin": {"password_hash": "5e884898da28047151d0e56f8dc6292773603d0d6aabbdd62a11ef721d1542d8", "email": "admin@corp.internal", "role": "admin"},
    "user1": {"password_hash": "6b86b273ff34fce19d6b804eff5a3f5747ada4eaa22f1d49c01e52ddb7875b4b", "email": "user1@corp.internal", "role": "user"}
}

SESSION_SECRET = os.environ.get("SESSION_SECRET", "default-secret-key-change-me")
CSRF_SECRET = os.environ.get("CSRF_SECRET", "csrf-token-secret-2024")

# Feature flag client configuration
FLAG_SERVICE_URL = os.environ.get("FLAG_SERVICE_URL", "http://localhost:8081")
FLAG_API_KEY = os.environ.get("FLAG_API_KEY", "")

async def get_feature_flag(flag_key: str, default: bool = False) -> bool:
    """Evaluate feature flag from remote flag service (Split.io compatible proxy)"""
    try:
        async with httpx.AsyncClient(timeout=2.0) as client:
            resp = await client.get(
                f"{FLAG_SERVICE_URL}/api/flags/{flag_key}",
                headers={"Authorization": f"Bearer {FLAG_API_KEY}"}
            )
            if resp.status_code == 200:
                data = resp.json()
                return data.get("treatment", "off") == "on"
    except Exception:
        pass
    return default

def generate_csrf_token(session_id: str) -> str:
    timestamp = str(int(time.time()) // 3600)
    return hmac.new(CSRF_SECRET.encode(), f"{session_id}:{timestamp}".encode(), hashlib.sha256).hexdigest()[:32]

def validate_csrf_token(session_id: str, token: str) -> bool:
    expected = generate_csrf_token(session_id)
    return hmac.compare_digest(expected, token)

def get_session_user(session_token: str = Cookie(default=None, alias="session")):
    if not session_token:
        return None
    try:
        parts = session_token.split(".")
        if len(parts) == 2:
            username = parts[0]
            sig = parts[1]
            expected_sig = hmac.new(SESSION_SECRET.encode(), username.encode(), hashlib.sha256).hexdigest()[:16]
            if hmac.compare_digest(sig, expected_sig):
                return username
    except Exception:
        pass
    return None

@app.post("/api/account/update-email")
async def update_email(
    request: Request,
    new_email: str = Form(...),
    csrf_token: str = Form(default=""),
    current_user: str = Depends(get_session_user)
):
    if not current_user:
        return Response(status_code=401, content="Unauthorized")

    # Feature flag controls whether CSRF validation is enforced
    # Flag: "csrf_enforcement_v2" - rollout of new CSRF middleware
    enforce_csrf = await get_feature_flag("csrf_enforcement_v2", default=False)

    if enforce_csrf:
        session_token = request.cookies.get("session", "")
        if not validate_csrf_token(session_token, csrf_token):
            return Response(status_code=403, content="CSRF validation failed")

    # Update user email
    if current_user in users_db:
        users_db[current_user]["email"] = new_email
        return {"status": "success", "message": f"Email updated to {new_email}"}
    return Response(status_code=404, content="User not found")

@app.post("/api/account/change-role")
async def change_role(
    request: Request,
    target_user: str = Form(...),
    new_role: str = Form(...),
    csrf_token: str = Form(default=""),
    current_user: str = Depends(get_session_user)
):
    if not current_user:
        return Response(status_code=401, content="Unauthorized")
    if users_db.get(current_user, {}).get("role") != "admin":
        return Response(status_code=403, content="Admin required")

    enforce_csrf = await get_feature_flag("csrf_enforcement_v2", default=False)

    if enforce_csrf:
        session_token = request.cookies.get("session", "")
        if not validate_csrf_token(session_token, csrf_token):
            return Response(status_code=403, content="CSRF validation failed")

    if target_user in users_db:
        users_db[target_user]["role"] = new_role
        return {"status": "success", "message": f"Role updated for {target_user}"}
    return Response(status_code=404, content="User not found")

@app.get("/api/account/profile")
async def get_profile(current_user: str = Depends(get_session_user)):
    if not current_user:
        return Response(status_code=401, content="Unauthorized")
    user = users_db.get(current_user, {})
    return {"username": current_user, "email": user.get("email"), "role": user.get("role")}

